<template>
  <div class="manager-page"><div class="page-heading"><div><div class="eyebrow">FACULTY</div><h1>教师管理</h1><p>维护教师账号，支持课程与作业发布。</p></div><el-button type="primary" round @click="handleAdd"><el-icon><Plus /></el-icon>新增教师</el-button></div><div class="card table-card"><div class="toolbar"><el-input v-model="query.name" clearable placeholder="搜索教师姓名" style="width:250px" @keyup.enter="search"><template #prefix><el-icon><Search /></el-icon></template></el-input><el-input v-model="query.username" clearable placeholder="搜索账号" style="width:220px" @keyup.enter="search"><template #prefix><el-icon><User /></el-icon></template></el-input><div class="grow"></div><span class="text-muted">共 {{total}} 位教师</span></div><el-table :data="rows" stripe><el-table-column label="教师" min-width="220"><template #default="{row}"><div class="user-cell"><img :src="row.avatar || '/images/avatars/teacher.jpg'"/><div><b>{{row.name}}</b><span>@{{row.username}}</span></div></div></template></el-table-column><el-table-column label="角色" width="100"><template #default><el-tag type="warning" effect="plain">教师</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><el-button text type="primary" @click="handleEdit(row)">编辑</el-button><el-button text type="danger" @click="del(row.id)">删除</el-button></template></el-table-column></el-table><div class="pagination-wrap"><el-pagination background layout="prev,pager,next" :total="total" :page-size="query.pageSize" v-model:current-page="query.pageNum" @current-change="load"/></div></div><el-dialog v-model="visible" :title="form.id?'编辑教师':'新增教师'" width="500px"><el-form :model="form" label-position="top"><el-form-item label="账号"><el-input v-model="form.username"/></el-form-item><el-form-item label="姓名"><el-input v-model="form.name"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" show-password :placeholder="form.id?'留空则不修改':'默认 123456'"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div>
</template>
<script setup>
import {reactive,ref,computed,onMounted} from 'vue';import request from '@/utils/request';import {ElMessage,ElMessageBox} from 'element-plus';const query=reactive({name:'',username:'',pageNum:1,pageSize:8});const data=reactive({rows:[],total:0}),rows=computed(()=>data.rows),total=computed(()=>data.total),visible=ref(false),form=reactive({});const load=()=>request.get('/teacher/selectPage',{params:query}).then(res=>{if(res.code==='200'){data.rows=res.data.list||[];data.total=res.data.total||0}});const search=()=>{query.pageNum=1;load()};const handleAdd=()=>{Object.assign(form,{id:null,username:'',name:'',password:'',role:'TEACHER'});visible.value=true};const handleEdit=row=>{Object.assign(form,row);form.password='';visible.value=true};const save=()=>request[form.id?'put':'post'](form.id?'/teacher/update':'/teacher/add',form).then(res=>{if(res.code==='200'){ElMessage.success('保存成功');visible.value=false;load()}else ElMessage.error(res.msg)});const del=id=>ElMessageBox.confirm('确认删除该教师？','提示').then(()=>request.delete('/teacher/delete/'+id).then(()=>{ElMessage.success('已删除');load()}));onMounted(load)
</script>
<style scoped>.user-cell{display:flex;align-items:center;gap:10px}.user-cell img{width:38px;height:38px;border-radius:50%;object-fit:cover}.user-cell div{display:flex;flex-direction:column;gap:4px}.user-cell span{font-size:10px;color:var(--muted)}</style>



